<script setup lang="ts">
import {computed,ref,watch} from 'vue';
import {buildTextDiff,diffDisplayText} from '../text-diff';
const props=defineProps<{before?:string;after?:string;path?:string;compact?:boolean}>();
const expanded=ref(false),pretty=ref(true),path=computed(()=>props.path??'');
const old=computed(()=>diffDisplayText(props.before,path.value,pretty.value)),next=computed(()=>diffDisplayText(props.after,path.value,pretty.value));
const model=computed(()=>buildTextDiff(old.value.text,next.value.text,props.compact?1:3,expanded.value));
const formatted=computed(()=>old.value.formatted||next.value.formatted);
watch(()=>[props.path,props.before,props.after],()=>{expanded.value=false;});
const sign=(kind:string)=>kind==='added'?'+':kind==='removed'?'−':' ';
</script>
<template><section class="text-patch" :class="{'text-patch-compact':compact}" aria-label="逐行文本差异">
  <div class="text-patch-tools"><span class="patch-removed">− {{model.deletions}}</span><span class="patch-added">+ {{model.additions}}</span><span>删除 / 新增 · 深色标记为行内变化</span><label v-if="/\.json$/i.test(path)"><input v-model="pretty" type="checkbox"/>JSON结构排版</label><button v-if="model.hiddenLines&&!model.limited" class="btn btn-ghost" @click="expanded=!expanded">{{expanded?'仅看变更':'展开上下文'}}</button><button v-else-if="expanded" class="btn btn-ghost" @click="expanded=false">仅看变更</button></div>
  <p v-if="formatted" class="text-patch-note">按 JSON 结构排版以定位字段；取消勾选可检查原始文本和格式变化。</p>
  <p v-if="model.unchanged" class="text-patch-note">{{formatted&&before!==after?'结构内容一致，可能仅排版不同；取消结构排版查看原始差异。':'文本内容没有变化。'}}</p>
  <p v-if="model.limited" class="text-patch-note" role="status">为保持页面流畅，文本过大或行数超过显示上限；请通过文件预览检查完整原文。此处不代表完整差异。</p>
  <p v-if="model.coarse" class="text-patch-note">内容差异较大，已按整段删增展示。</p>
  <div v-if="model.hunks.length" class="text-patch-scroll" tabindex="0" aria-label="差异内容"><table class="text-patch-table"><tbody><template v-for="(hunk,index) in model.hunks" :key="index"><tr class="patch-hunk"><td colspan="4"><span v-if="hunk.hiddenBefore">省略 {{hunk.hiddenBefore}} 行未变内容 · </span>{{hunk.header}}</td></tr><tr v-for="(line,lineIndex) in hunk.lines" :key="lineIndex" :class="'patch-'+line.kind" :data-diff-kind="line.kind"><td class="patch-number">{{line.oldLine??''}}</td><td class="patch-number">{{line.newLine??''}}</td><td class="patch-sign" :aria-label="line.kind==='added'?'新增':line.kind==='removed'?'删除':'未变'">{{sign(line.kind)}}</td><td class="patch-content"><code><template v-for="(part,partIndex) in line.parts" :key="partIndex"><mark v-if="part.changed" :class="'mark-'+line.kind">{{part.text||' '}}</mark><template v-else>{{part.text}}</template></template><span v-if="!line.text"> </span></code><small v-if="line.kind!=='context'&&line.ending!=='LF'" class="patch-ending">{{line.ending==='无换行'?'末行无换行':line.ending}}</small></td></tr></template></tbody></table></div>
</section></template>
<style scoped>
.text-patch{min-width:0}.text-patch-tools{display:flex;gap:12px;align-items:center;flex-wrap:wrap;padding:11px 15px;border-bottom:1px solid var(--line);font-size:11px;color:var(--muted)}.text-patch-tools>label{margin-left:auto;display:flex;align-items:center;gap:6px}.text-patch-tools .btn{font-size:10px;padding:3px 7px}.text-patch-tools input{accent-color:var(--primary)}.patch-added{color:var(--success)}.patch-removed{color:var(--danger)}.text-patch-note{padding:9px 15px;font-size:11px;color:var(--muted);line-height:1.8;background:var(--surface)}.text-patch-scroll{overflow:auto;max-height:650px;outline-color:var(--primary)}.text-patch-table{width:100%;border-collapse:collapse;table-layout:auto;font:12px/1.7 var(--font-mono,monospace)}.text-patch-table td{padding:1px 8px;border:0;vertical-align:middle}.patch-number{width:45px;min-width:35px;text-align:right!important;color:var(--subtle);user-select:none;border-right:1px solid var(--line)!important}.patch-sign{width:22px;min-width:22px;text-align:center;user-select:none}.patch-content{white-space:pre-wrap;overflow-wrap:anywhere;min-width:180px}.patch-hunk td{background:var(--primary-soft);color:var(--muted);padding:6px 12px;font-size:10px}.text-patch-table .patch-added{background:color-mix(in srgb,var(--success) 8%,var(--surface))}.text-patch-table .patch-removed{background:color-mix(in srgb,var(--danger) 8%,var(--surface))}.text-patch-table mark{color:inherit;border-radius:2px;padding:0;font:inherit}.mark-added{background:color-mix(in srgb,var(--success) 28%,transparent)}.mark-removed{background:color-mix(in srgb,var(--danger) 28%,transparent)}.patch-ending{display:inline-block;margin-left:12px;color:var(--muted);font:10px var(--font-mono,monospace);border:1px solid var(--line);padding:0 4px}.text-patch-compact .text-patch-tools{padding:5px 7px;gap:8px;font-size:10px}.text-patch-compact .text-patch-tools>span:nth-child(3){display:none}.text-patch-compact .text-patch-scroll{max-height:330px}.text-patch-compact .patch-number{width:24px;min-width:24px}.text-patch-compact .text-patch-table{font-size:11px}.text-patch-compact .patch-content{min-width:120px}.text-patch-compact .text-patch-note{padding:5px 8px;font-size:10px}@media(max-width:600px){.text-patch-tools{padding:9px;gap:8px}.text-patch-table{font-size:10px}.patch-number{width:26px;min-width:26px}.text-patch-table td{padding:1px 5px}}
</style>
